<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';$e=' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
$sql=[
"ALTER TABLE support_tickets ADD UNIQUE KEY uq_split_ticket_scope(id,customer_id,department_id)",
"ALTER TABLE support_messages ADD UNIQUE KEY uq_split_message_scope(id,ticket_id,customer_id)",
"INSERT INTO identity_permissions(code) VALUES ('support.ticket.split')",
"INSERT INTO identity_role_permissions(role_id,permission) SELECT id,'support.ticket.split' FROM identity_roles WHERE name IN ('Super Admin','Destek')",
"CREATE TABLE support_ticket_splits(id $id PRIMARY KEY,source_id $id NOT NULL UNIQUE,child_id $id NOT NULL UNIQUE,customer_id $id NOT NULL,department_id $id NOT NULL,requester_id $id NOT NULL,source_version INT UNSIGNED NOT NULL,actor_id $id NOT NULL,session_id $id NOT NULL,identity_version INT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),CHECK(source_id<>child_id),UNIQUE KEY uq_split_edge_scope(id,source_id,child_id,customer_id,department_id),FOREIGN KEY(id) REFERENCES support_work_events(id),FOREIGN KEY(source_id,customer_id,department_id) REFERENCES support_tickets(id,customer_id,department_id),FOREIGN KEY(child_id,customer_id,department_id) REFERENCES support_tickets(id,customer_id,department_id),FOREIGN KEY(requester_id) REFERENCES identity_users(id),FOREIGN KEY(actor_id) REFERENCES identity_users(id),FOREIGN KEY(session_id) REFERENCES identity_sessions(id))$e",
"CREATE TABLE support_split_members(ticket_id $id PRIMARY KEY,split_id $id NOT NULL,side VARCHAR(8) NOT NULL CHECK(side IN ('SOURCE','CHILD')),UNIQUE KEY uq_split_side(split_id,side),FOREIGN KEY(ticket_id) REFERENCES support_tickets(id),FOREIGN KEY(split_id) REFERENCES support_ticket_splits(id))$e",
"CREATE TABLE support_split_messages(split_id $id NOT NULL,message_id $id NOT NULL UNIQUE,source_id $id NOT NULL,child_id $id NOT NULL,customer_id $id NOT NULL,department_id $id NOT NULL,PRIMARY KEY(split_id,message_id),FOREIGN KEY(split_id,source_id,child_id,customer_id,department_id) REFERENCES support_ticket_splits(id,source_id,child_id,customer_id,department_id),FOREIGN KEY(message_id,source_id,customer_id) REFERENCES support_messages(id,ticket_id,customer_id))$e",
"CREATE TRIGGER support_split_edge_scope BEFORE INSERT ON support_ticket_splits FOR EACH ROW BEGIN IF NOT EXISTS(SELECT 1 FROM support_tickets a JOIN support_tickets b ON b.id=NEW.child_id WHERE a.id=NEW.source_id AND a.requester_id=NEW.requester_id AND b.requester_id=NEW.requester_id AND b.status='NEW') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Split requester or child mismatch'; END IF; END",
"CREATE TRIGGER support_split_member_scope BEFORE INSERT ON support_split_members FOR EACH ROW BEGIN IF NOT EXISTS(SELECT 1 FROM support_ticket_splits WHERE id=NEW.split_id AND ((NEW.side='SOURCE' AND source_id=NEW.ticket_id) OR (NEW.side='CHILD' AND child_id=NEW.ticket_id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Split endpoint mismatch'; END IF; END",
"CREATE TRIGGER support_split_public BEFORE INSERT ON support_split_messages FOR EACH ROW BEGIN IF NOT EXISTS(SELECT 1 FROM support_messages WHERE id=NEW.message_id AND ticket_id=NEW.source_id AND customer_id=NEW.customer_id AND customer_visible=TRUE AND type IN ('customer_reply','staff_reply')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Public split message required'; END IF; END",
];
foreach(['support_ticket_splits','support_split_members','support_split_messages'] as $table){foreach(['UPDATE','DELETE'] as $verb){$suffix=strtolower($verb);$sql[]="CREATE TRIGGER {$table}_no_{$suffix} BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable split provenance'";}}
return $sql;
